package app.bookey.domain.club; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Modifying; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; import java.time.Instant; import java.util.List; public interface ClubMeetingAttendeeRepository extends JpaRepository<ClubMeetingAttendee,ClubMeetingAttendee.Key>{long countByMeetingId(Long id);List<ClubMeetingAttendee> findAllByMeetingId(Long id);
 /** 클럽을 나간 사람을 아직 시작하지 않은 모임의 참여 명단에서 뺀다 — 정원도 함께 풀린다. */
 @Modifying @Query("delete from ClubMeetingAttendee a where a.userId=:userId and a.meetingId in (select m.id from ClubMeeting m where m.clubId=:clubId and m.status='OPEN' and m.startsAt>:now)") void deleteUpcomingByClubIdAndUserId(@Param("clubId") Long clubId,@Param("userId") Long userId,@Param("now") Instant now);}
